<script lang="ts">
 import {page} from '$app/stores';import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import PrivilegeEditor from '$lib/components/database/PrivilegeEditor.svelte';import Operations from '$lib/components/database/Operations.svelte';import CreateUser from '$lib/components/database/CreateUser.svelte';import {databaseState,command} from '$lib/database/store';import {workspace} from '$lib/stores/workspace';import {usersFor,permissions,privilegeLabel,host,port,adminTool,sizeLabel} from '$lib/database/model';
 let edit='',grant='',error='',showNew=false,showTool=false,confirmDelete='',selectedProject='';
 $: id=$page.params.id||'';$: d=$databaseState.databases.find(d=>d.id===id);$: users=usersFor($databaseState,id);$: available=$databaseState.users.filter(u=>d&&u.engine===d.engine&&!Object.prototype.hasOwnProperty.call(u.grants,id));$: projects=$workspace.projects.filter(p=>!$databaseState.databases.some(x=>x.project===p.id));
 function run(fn:()=>void){try{error='';fn();}catch(e){error=e instanceof Error?e.message:'Action failed.';}}
</script>
{#if d}<Heading title="Manage Database" subtitle={d.name+' · '+d.engine}><a class="btn secondary" href="/databases">Manage Databases</a><a class="btn secondary" href="/databases/users">Manage Users</a><button class="btn secondary" on:click={()=>showTool=!showTool}>{adminTool(d.engine)} <Icon name="External"/></button></Heading>
<div class="stack">{#if error}<p class="error" role="alert">{error}</p>{/if}{#if showTool}<div class="callout"><strong>{adminTool(d.engine)} preview</strong><p>External database tools are not connected in this development build.</p></div>{/if}
<section class="card"><div class="section-title"><h3>Overview</h3><p class="subtitle">Detailed information about the database · sample metadata.</p></div><dl class="db6-facts">{#each [['Database Name',d.name],['Default Charset',d.engine==='PostgreSQL'?'UTF8':'utf8mb4'],['Default Collation',d.engine==='PostgreSQL'?'Server default':'utf8mb4_unicode_ci'],['Size',sizeLabel(d.bytes)],['Users',users.length],['Tables',d.tables.length],['Views',0],['Events',d.engine==='PostgreSQL'?'Not applicable':0],['Triggers',0],['Routines',0]] as fact,i}<div class={'db6-fact '+(i===0?'db6-span-6':'db6-span-3')}><span class="icon-box"><Icon name={i===0?'Databases':'File'}/></span><div class="grow"><dt>{fact[0]}</dt><dd>{fact[1]}</dd></div></div>{/each}</dl></section>
<section class="card table-card"><div class="table-head"><div class="row between wrap"><div><h3>User Access</h3><p class="subtitle">Manage users, privileges and allowed connection hosts.</p></div><button class="btn secondary small" on:click={()=>showNew=!showNew}>Create user</button></div></div><div class="table-wrap"><table><thead><tr><th>User Name</th><th>Privileges</th><th>Actions</th></tr></thead><tbody>{#each users as u (u.id)}<tr><td><a class="link-btn mono native-path" href={'/databases/users/'+u.id}>{u.name}</a></td><td>{privilegeLabel(u.engine,u.grants[id])}</td><td><div class="table-actions"><a class="btn secondary small" href={'/databases/users/'+u.id}>Manage</a><button class="btn secondary small" on:click={()=>edit=edit===u.id?'':u.id}>Privileges</button><button class="btn danger small" on:click={()=>{if(window.confirm('Revoke this user’s access to '+d?.name+'?'))run(()=>command({type:'revoke',database:id,user:u.id}));}}>Revoke Access</button></div></td></tr>{#if edit===u.id}<tr><td colspan="3">{#key u.id}<PrivilegeEditor engine={u.engine} initial={u.grants[id]} onSave={(values)=>{command({type:'grant',database:id,user:u.id,privileges:values});edit='';}} onCancel={()=>edit=''}/>{/key}</td></tr>{/if}{:else}<tr><td colspan="3">No users have access yet.</td></tr>{/each}</tbody></table></div><form class="stack" style="padding:24px" on:submit|preventDefault={()=>run(()=>{if(!d)return;command({type:'grant',database:id,user:grant,privileges:permissions(d.engine)});grant='';})}><h4 style="margin:0">Grant access for additional user</h4><div class="native-inline"><label class="field grow">Existing user<select bind:value={grant} required><option value="">Select new user…</option>{#each available as u}<option value={u.id}>{u.name}</option>{/each}</select><small>The user will be granted all available privileges.</small></label><button type="submit" class="btn primary" disabled={!grant}>Grant full access</button></div></form></section>
{#if showNew}<CreateUser database={id} fixedEngine={d.engine}/>{/if}<Operations database={d}/>
<div class="grid2"><section class="card stack"><h3>Connection details</h3><div class="summary-list">{#each [['Host',host(d.engine)],['Port',port(d.engine)],['Database',d.name],['Access','Private by default']] as pair}<div><span>{pair[0]}</span><strong>{pair[1]}</strong></div>{/each}</div><small>Illustrative internal connection details. Remote hosts are configured per user. TLS is required for public connections in production.</small></section><section class="card stack"><h3>Linked project</h3>{#if d.project}<div class="row between wrap"><a class="link-btn" href={'/projects/'+d.project+'/database'}>{$workspace.projects.find(p=>p.id===d?.project)?.name||d.project}</a><button class="btn secondary small" on:click={()=>run(()=>command({type:'link',database:id,project:null}))}>Disconnect</button></div>{:else}<form class="stack" on:submit|preventDefault={()=>run(()=>command({type:'link',database:id,project:selectedProject||null}))}><label class="field">Project<select bind:value={selectedProject} required><option value="">Select an available project</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button class="btn secondary" type="submit" disabled={!selectedProject}>Connect project</button></form>{/if}<small>Database remains independent of the project.</small></section></div>
<section class="card"><h3>Operation history</h3>{#each d.operations as op}<div class="setting-row"><span>{op.text}</span><small>{new Date(op.at).toLocaleString()}</small></div>{:else}<p class="subtitle">No operations recorded yet.</p>{/each}</section><section class="card stack"><h3>Delete database</h3><p class="subtitle">Removes only the sample database and its grants, not the users.</p><label class="field">Type {d.name} to confirm<input bind:value={confirmDelete}/></label><div><button class="btn danger" disabled={confirmDelete!==d.name} on:click={()=>run(()=>{command({type:'delete-database',database:id});void goto('/databases');})}>Delete sample database</button></div></section></div>
{:else}<Heading title="Database not found" subtitle="This database is not in your workspace."/><a class="btn secondary" href="/databases">Manage Databases</a>{/if}
